class _Tee:
    "Copy one redirected descriptor to its original destination and an in-memory buffer."
    def __init__(self, fd):
        self.fd, self.buf, self.thread = fd, bytearray(), None
        self.saved = self.r = self.w = None
    def start(self):
        self.saved = os.dup(self.fd)              
        self.r, self.w = os.pipe()
        os.dup2(self.w, self.fd)
        os.close(self.w)
        self.w = None
        self.thread = threading.Thread(target=self._pump, daemon=True)
        self.thread.start()
    def _pump(self):
        while True:
            try: b = os.read(self.r, 4096)
            except OSError: break
            if not b: break
            self.buf += b
            del self.buf[:-MAX_KEEP]
            try: os.write(self.saved, b)
            except OSError: pass
    def stop(self):
        if self.saved is not None:
            try: os.dup2(self.saved, self.fd)                 # drops the last write end; the pump then reads EOF
            except OSError: pass
        if self.thread is not None: self.thread.join(timeout=1.0)   # before the close, or the bytes still in the pipe go
        if self.r is not None:
            try: os.close(self.r)
            except OSError: pass
        if self.saved is not None:
            try: os.close(self.saved)
            except OSError: pass
        return self.buf.decode('utf-8', 'replace')

