class captured:
    "Copy what is written to descriptors 1 and 2 into `text`, while the output still reaches the terminal."
    _lock = threading.Lock()
    def __init__(self, fds=(1, 2), enabled=None):
        self.fds = fds
        self.text = ''
        self.enabled = ((env('NO_NATIVE_CAPTURE') or '').lower() not in ('1', 'true', 'yes') if enabled is None else enabled)
        self._tees, self._held = [], False
    def __enter__(self):
        if not self.enabled: return self
        if not self._lock.acquire(timeout=0.5): return self
        self._held = True
        for fd in self.fds:
            t = _Tee(fd)
            try:
                sys.stdout.flush(); sys.stderr.flush()
                t.start()
                self._tees.append(t)
            except Exception: break
        return self
    def __exit__(self, *exc):
        parts = []
        for t in reversed(self._tees):
            try: parts.append(t.stop())
            except Exception: pass
        self._tees = []
        if self._held:
            self._held = False
            try: self._lock.release()
            except RuntimeError: pass
        self.text = ''.join(reversed(parts))
        return False

    @property
    def problems(self):
        "The captured lines worth reporting, as one string, or ''."
        return '\n'.join(interesting(self.text))

# %% ../nbs/01_runtime.ipynb #1b16a11e
def capture(fn, *a, **kw):
    "Call `fn` and return `(result, problems)`; an exception carries them out too."
    cap, err, out = captured(), None, None
    with cap:
        try: out = fn(*a, **kw)
        except Exception as e: err = e
    if err is not None:
        err.native_output = cap.problems
        raise err
    return out, cap.problems

