CHARS_PER_TOKEN = 3.25
RESERVE = 16_384             # tokens of headroom below the window
KEEP_RECENT = 20_000         # tokens of recent conversation left uncompacted
SOFT_LINE = 150_000          # tokens past which the next clean turn boundary hands off to a fresh context
HARD_LINE = 250_000          # tokens past which the conversation is compacted, whatever the window
SUMMARY_PREFIX = 'Previous conversation summary:\n'
SURGICAL_POLICY = {'user': 2000, 'assistant': 150, 'call': 60, 'result': 35}

# %% ../nbs/01_runtime.ipynb #be51204d
def estimate_tokens(text, count=None):
    "Tokens in `text`: exact via `count` when a tokenizer is at hand, `CHARS_PER_TOKEN` otherwise."
    if not text: return 0
    if count is not None:
        try: return count(text)
        except Exception: pass
    return max(1, math.ceil(len(text) / CHARS_PER_TOKEN))

def halvings(budget, tries=3, floor=256):
    "A budget and its halvings, to retry a prompt whose fit was only estimated."
    if not budget: return [budget]
    return [budget] + [min(budget, max(floor, budget >> i)) for i in range(1, tries)]

def threshold(ctx, reserve=None):
    "The token count at which a conversation should be compacted, or None when there is no window. `reserve` is config.toml's `window.reserve`, else `RESERVE`."
    if not ctx or ctx <= 0: return None
    if reserve is None: reserve = setting('window.reserve', RESERVE)
    return max(1, ctx - min(reserve, max(1, ctx // 4)))

def should_compact(used, ctx, reserve=None):
    "Whether `used` tokens against a `ctx` window has crossed the line."
    t = threshold(ctx, reserve)
    return bool(t and used >= t)

def done_items(summary):
    "The lines under a summary's `### Done` heading, up to the next heading, or `''`."
    m = re.search(r'^### Done[ \t]*\n(.*?)(?=^#|\Z)', summary or '', re.M | re.S)
    return m.group(1).strip() if m else ''

