class Compactor:
    "Decide when to compact, and do it."
    def __init__(self,
                 reserve=None,               # None reads config.toml's `window.reserve`, else `RESERVE`, each time
                 keep_recent=None,           # None reads `window.keep_recent`, else `KEEP_RECENT`
                 auto=True,                  # the agent compacts on crossing the threshold only when true; `Compactor` itself ignores it
                 kernel_alive=True,          # whether the kernel survived; passed to `reorient`
                 on_compact=None,            # called with each new summary
                 strategy='summary',          # 'summary' or 'surgical'; 'surgical' calls no model
                 soft=None,                  # None reads `compaction.soft`, else `SOFT_LINE`
                 hard=None):                 # None reads `compaction.hard`, else `HARD_LINE`
        self._reserve, self._keep_recent, self.auto = reserve, keep_recent, auto
        self._soft, self._hard = soft, hard
        self.strategy = strategy
        self.kernel_alive, self.on_compact = kernel_alive, on_compact
        self.count = 0
        self.last = ''
        self.note = 'not compacted'

    @property
    def reserve(self): return setting('window.reserve', RESERVE) if self._reserve is None else self._reserve
    @reserve.setter
    def reserve(self, v): self._reserve = v
    @property
    def keep_recent(self): return setting('window.keep_recent', KEEP_RECENT) if self._keep_recent is None else self._keep_recent
    @keep_recent.setter
    def keep_recent(self, v): self._keep_recent = v

    @property
    def soft(self): return setting('compaction.soft', SOFT_LINE) if self._soft is None else self._soft
    @property
    def hard(self): return setting('compaction.hard', HARD_LINE) if self._hard is None else self._hard

    def due(self, backend):
        "Whether `backend` has crossed the hard line, or its window's threshold when that is lower."
        t = threshold(backend.spec.ctx, self.reserve)
        return backend.used_tokens >= (min(t, self.hard) if t else self.hard)

    def soft_due(self, backend):
        "Whether `backend` is past the soft line but not yet due: the band where a clean turn boundary hands off."
        return backend.used_tokens >= self.soft and not self.due(backend)

    def budget(self, ctx=0, overhead=0):
        "How much recent conversation to keep, for a window of `ctx` holding `overhead` besides."
        if not ctx: return self.keep_recent
        return min(self.keep_recent, max(256, max(256, ctx - overhead) // 2))

    def overhead(self, backend, msgs, count=None):
        "The window's non-conversation load, and the per-message sizes measured to find it."
        sizes = [estimate_tokens(resp_text(m), count) + 8 for m in msgs]
        used = getattr(backend, 'used_tokens', 0) or 0
        return (max(0, used - sum(sizes)) if used else 0), sizes

    def _keep(self, msgs, count=None, ctx=0, overhead=0, sizes=None):
        "The tail to keep uncompacted, newest-first until the budget runs out. Whole messages only."
        if sizes is None: sizes = [estimate_tokens(resp_text(m), count) + 8 for m in msgs]
        budget = self.budget(ctx, overhead)
        if sizes: budget = min(budget, max(256, sum(sizes)//2))
        kept, used = [], 0
        for m, n in zip(reversed(msgs), reversed(sizes)):
            if used + n > budget and kept: break
            kept.append(m); used += n
        kept.reverse()
        while kept and kept[0].get('role') != 'user': kept.pop(0)
        return kept

    def compact(self, backend, summariser, extra='', summary_ctx=0, summary_output=4096, summary_count=None,
                fresh=False):  # keep no recent messages and always summarise: a handoff to a fresh context
        "Summarise `backend`'s history with `summariser(prompt, sp)`, replace it, return the summary."
        msgs = list(backend.hist or [])
        if not msgs:
            self.note = 'nothing to compact'
            return ''
        count = backend.count_tokens
        oh = self.overhead(backend, msgs, count)
        oh, sizes = oh if isinstance(oh, tuple) else (oh, None)
        keep = [] if fresh else self._keep(msgs, count, getattr(backend.spec, 'ctx', 0), oh, sizes)
        older = msgs[:len(msgs) - len(keep)]
        if not older:
            self.note = 'everything is recent; nothing to compact'
            return ''
        if self.strategy == 'surgical' and not fresh:
            text = surgical_history(older, count=backend.count_tokens)
            head = SUMMARY_PREFIX + text + '\n\n' + reorient(self.kernel_alive)
            try: backend.replace_hist(head, keep)
            except Exception as e:
                self.note = f'compaction checkpoint written but history not replaced ({agent_err(e)})'
                return text
            self.count += 1; self.last = text
            self.note = f'surgically compacted {len(older)} message(s), kept {len(keep)}'
            if self.on_compact:
                try: self.on_compact(text)
                except Exception: pass
            return text
        input_budget = None
        if summary_ctx:
            sp_tokens = estimate_tokens(SUMMARISE_SP, summary_count)
            input_budget = max(128, summary_ctx - summary_output - sp_tokens - 64)
        # an estimated budget can still overflow; retry on halvings
        text, err = '', None
        for b in halvings(input_budget):
            try:
                if (text := fold_summary(older, summariser, extra, b, summary_count)): break
            except Exception as e: err = e
        if not text:
            self.note = (f'compaction failed ({agent_err(err)})' if err is not None
                         else 'the summarizer returned nothing; conversation left alone')
            return ''
        head = SUMMARY_PREFIX + text + '\n\n' + reorient(self.kernel_alive)
        try: backend.replace_hist(head, keep)
        except Exception as e:
            self.note = f'compaction summary written but history not replaced ({agent_err(e)})'
            return text
        self.count += 1
        self.last = text
        self.note = f'handed off {len(older)} message(s) to a fresh context' if fresh else f'compacted {len(older)} message(s), kept {len(keep)}'
        if self.on_compact:
            try: self.on_compact(text)
            except Exception: pass
        return text

