class Backend:
    "The contract a model engine meets: start, send or stream a turn, count tokens, and replace history."
    kind='?'
    narrates=True   # the text before each tool call reaches `hist` or the stream; see `QUIET_RUNTIMES`
    _tag_reminded=False
    turn_error=''   # why the last `send` or `stream` gave a failure note instead of a reply; '' when it answered
    turn_budget=False   # whether that failure was the model's own budget stop (`ClaudeError.budget`)
    on_notice=None  # where a frontend shows a status note mid-turn; set on the class, as `TokenLogger.sink` is
    def __init__(self,spec,sp='',tools=(),approve=None,tool_max_len=None,shared=False,**kw):
        self.spec,self.sp,self.tools,self.approve=spec,sp,list(tools),approve
        self.tool_max_len,self.shared,self.kw=tool_max_len,shared,kw
        self.chat,self.use,self.note=None,Usage(model=spec.model_id),'not started'
        self.problems,self.last_native,self._tried,self.run=[], '', False, None
        self._resume_hist=None
        self.fell_back,self._refused=[],set()   # what this backend gave up to answer, for the caller to be told; per-turn levels the model refused
        self._used,self._rewrote,self._est=0,None,0
        self.spill,self.how=_unsaved,''
        self.lock=threading.Lock()
    @property
    def ready(self): return self.chat is not None
    @property
    def busy(self): return self.lock.locked()
    @property
    def hist(self): return getattr(self.chat,'hist',[]) if self.chat else []
    def notice(self,text):
        "Show a status note now: the run's status, and the frontend's `on_notice`, else a problem."
        if self.run is not None: self.run.set_status(text)
        if (f:=type(self).on_notice) is not None:
            try: return f(text)
            except Exception: pass
        self.problem(text)
    def problem(self,text):
        text=(text or '').strip()
        if text and (not self.problems or self.problems[-1]!=text): self.problems.append(text)
        del self.problems[:-20]
        return text
    def _failed(self,what,e):
        native=getattr(e,'native_output','') or ''
        self.note=f'{self.spec.name} {what} ({agent_err(e)})'+(f' -- {native}' if native else '')
        return self.problem(self.note)
    def start(self):
        if self._tried:return self.chat
        self._tried=True
        try:
            self.chat=self._start()
            if self._resume_hist is not None:
                self.restore_hist(self._resume_hist); self._resume_hist=None
            self.note=f'{len(self.tools)} tools'
        except Exception as e:self.chat=None; self._failed('unavailable',e)
        return self.chat
    def retry(self): self._tried,self.chat=False,None; return self.start()
    def set_approve(self,approve):
        self.approve=approve
        if self.chat:self.chat.approve=approve
        return self
    def refresh(self,sp,tools):
        self.sp,self.tools=sp,list(tools)
        if self.chat:self._refresh(); self.note=f'{len(self.tools)} tools'
        return self
    def close(self):
        if aux:=getattr(self,'_oneshot_chat',None):
            try:aux.close()
            except Exception:pass
            self._oneshot_chat=None
        if self.chat:
            try:self.chat.close()
            except Exception:pass
            self.chat=None
    def cancel(self):
        "Ask this backend's chat to stop the turn in flight."
        if not self.chat:return False
        f=getattr(self.chat,'cancel',None)
        if f is None:
            self.problem(f'{self.spec.name} cannot be stopped mid-turn')
            return False
        try:f()
        except Exception as e:self._failed('could not be stopped',e); return False
        return True
    def _sync_callbacks(self):
        "Give the live chat every registered callback it is missing. Callers hold `lock`."
        add = getattr(self.chat, 'add_cb', None)
        if add is None: return
        held = getattr(self.chat, 'cbs', ())
        for cb in getattr(self, '_callbacks', ()):
            if not any(isinstance(x, cb) for x in held): add(cb)
    def send(self,msg,run=None,**kw):
        self.turn_error,self.turn_budget='',False
        if self.start() is None:self.turn_error=self.note; return self.note
        with self.lock:
            self.run=run
            self._tag_reminded=False
            self._sync_callbacks()
            try:
                tried=set()
                while True:
                    try:
                        out=self._send(msg,**kw)
                        if run is not None and run.cancelled:return ''
                        self.use=self._usage(); self._check_reply(out)
                        if not self._tag_reminded and self._needs_tag_retry(out):
                            self._tag_reminded=True
                            out=self._send(TAG_REMINDER,**kw); self.use=self._usage()
                        return out or self._empty()
                    except Exception as e:
                        if run is not None and run.cancelled:return ''
                        if (why:=self._recover(e)) in tried or not why:
                            # a failed run can still have been paid for: its cost is already in the chat's `use`
                            self.use,self.turn_budget=self._usage(),bool(getattr(e,'budget',False))
                            self.turn_error=agent_err(e); return self._failed('failed',e)
                        tried.add(why)
            finally:self.run=None
    def stream(self,msg,run=None,**kw):
        self.turn_error,self.turn_budget='',False
        if self.start() is None:self.turn_error=self.note; yield self.note; return
        with self.lock:
            self.run=run
            self._tag_reminded=False
            self._sync_callbacks()
            try:
                tried=set()
                while True:
                    n,buf=0,[]
                    try:
                        for c in self._stream(msg,**kw):
                            if run is not None and run.cancelled:return
                            n+=len(c or ''); buf.append(c or ''); yield c
                        if run is not None and run.cancelled:return
                        self.use=self._usage()
                        self._check_reply(''.join(buf))
                        if not self._tag_reminded and self._needs_tag_retry(''.join(buf)):
                            self._tag_reminded=True
                            yield '\n\n'
                            for c2 in self._stream(TAG_REMINDER,**kw):
                                if run is not None and run.cancelled:return
                                n+=len(c2 or ''); yield c2
                            self.use=self._usage()
                        if not n:yield self._empty(True)
                        return
                    except Exception as e:
                        if run is not None and run.cancelled:return
                        # retry only before any chunk was shown
                        if n or not (why:=self._recover(e)) or why in tried:
                            self.use,self.turn_budget=self._usage(),bool(getattr(e,'budget',False))
                            self.turn_error=agent_err(e); yield f'\n\n{self._failed("failed",e)}'; return
                        tried.add(why)
            finally:self.run=None
    def _recover(self,e):
        "Fix what made `e` happen and return its cause, retried once per cause in a turn. False by default."
        return False
    def _check_reply(self,text):
        "Look at a finished reply for a failure the transport could not raise. Nothing by default."
        return text
    def _needs_tag_retry(self,text):
        "Whether this reply narrated a tool call instead of emitting one. No by default."
        return False
    def _empty(self,strict=False):
        why=f'{self.spec.name} returned nothing'+(f' -- {self.last_native}' if self.last_native else '')
        return self.problem(why) if strict else (f'({why})' if self.last_native else '(no reply)')
    
    def _fit_oneshot(self,prompt,sp='',max_tokens=None):
        "Cut `prompt` to the window left after `sp` and the reply."
        ctx=self.spec.ctx
        if not ctx:return prompt
        room=ctx-self.count_tokens(sp)-(oneshot_tokens(ctx) if max_tokens is None else max_tokens)-ONESHOT_HEADROOM
        if room<=0 or self.count_tokens(prompt)<=room:return prompt
        body=prompt
        for _ in range(6):
            n=self.count_tokens(ONESHOT_CUT+body)
            if n<=room:break
            body=body[-max(1,int(len(body)*room*.95/n)):]
        return ONESHOT_CUT+body

    def oneshot(self,prompt,sp='',max_tokens=None,job='one-shot',if_busy=''):
        "Ask one question in a throwaway conversation; `job` names a failure, and `if_busy` is the answer while another call holds the backend."
        if self.start() is None:return ''
        if not self.lock.acquire(False):return if_busy
        try:return answer_only(self._oneshot(self._fit_oneshot(prompt,sp,max_tokens),sp,max_tokens) or '')
        except Exception as e:self._failed(f'{job} failed',e); return ''
        finally:self.lock.release()
    
    def spawn(self,sp='',tools=(),**kw): raise NotImplementedError
    def replace_hist(self,summary,keep=()):
        if not self.chat:raise RuntimeError('nothing to compact: the model is not running')
        self._replace_hist(summary,list(keep)); return self._rewritten()
    
    def snapshot_hist(self):
        "A detached model-history checkpoint suitable for an in-process branch, pending history included; pictures become placeholders."
        # a backend that has not started holds a resumed conversation in `_resume_hist`, not `hist`
        return strip_hist_media(copy.deepcopy(list(self.hist if self.chat else (self._resume_hist or []))))
    
    def resume_hist(self,hist):
        "Restore canonical history now, or after this backend starts lazily."
        if self.chat:return self.restore_hist(hist)
        self._resume_hist=copy.deepcopy(list(hist or [])); return self
    
    def restore_hist(self,hist):
        "Restore a checkpoint and rebuild provider conversation state."
        if not self.chat:raise RuntimeError('nothing to restore: the model is not running')
        self.chat.hist[:]=copy.deepcopy(list(hist or []))
        recreate=getattr(self.chat,'_recreate_conv',None)
        if recreate:recreate()
        return self._rewritten()
    
    def _rewritten(self):
        "Note that `hist` changed under the chat: its last reported count no longer holds, so `used_tokens` estimates until it reports again."
        try: self._rewrote,self._est=self.chat.token_count,self.window_tokens()
        except Exception: pass
        return self
    
    def base_tokens(self):
        "What the briefing and the tool schemas alone take of the window, before `margin`."
        specs=getattr(self.chat,'toolspecs',None) or []
        return self.count_tokens(self.sp)+(self.count_tokens(json.dumps(specs,default=str)) if specs else 0)

    def window_tokens(self):
        "What the window holds, estimated with `margin`: the briefing, the tool schemas, and every message."
        return math.ceil(margin()*(self.base_tokens()+sum(msg_tokens(m,self.count_tokens) for m in self.hist)))
    
    def trim(self,need):
        "Free about `need` tokens from the oldest tool results, then the oldest pictures; returns what was freed."
        if not self.chat or not (freed:=trim_hist(self.hist,need,self.count_tokens,save=self.spill,how=self.how)):return 0
        if recreate:=getattr(self.chat,'_recreate_conv',None):recreate()
        self._rewritten(); return freed

    def shrink_recent(self,need,keep=2):
        "Cut about `need` tokens from the newest `keep` messages a person or a tool wrote, largest first: text to an excerpt, extra pictures to files. Returns what was freed."
        if not self.chat or need<=0:return 0
        tok,freed=lambda m:msg_tokens(m,self.count_tokens),0
        for m in sorted([m for m in self.hist[-keep:] if m.get('role') in ('user','tool')],key=tok,reverse=True):
            if freed>=need:break
            n=tok(m); m['content']=fit_content(m.get('content'),max(64,n-(need-freed)),self.spill,self.how,self.count_tokens)
            freed+=n-tok(m)
        if freed:
            if recreate:=getattr(self.chat,'_recreate_conv',None):recreate()
            self._rewritten()
        return freed
    
    def revise_last_assistant(self,text):
        "Replace the last prose assistant message in a restored checkpoint."
        if not self.chat:raise RuntimeError('nothing to revise: the model is not running')
        msg=next((m for m in reversed(self.chat.hist) if isinstance(m,dict) and m.get('role')=='assistant' and not m.get('tool_calls')),None)
        if msg is None:raise ValueError('checkpoint has no assistant response')
        msg['content']=str(text)
        msg.pop('channels',None); msg.pop('usage',None)
        recreate=getattr(self.chat,'_recreate_conv',None)
        if recreate:recreate()
        return self
    
    def count_tokens(self,text):
        try:return self.chat.count_tokens(text or '') if self.chat else estimate_tokens(text)
        except Exception:return estimate_tokens(text)
    
    @property
    def used_tokens(self):
        "Tokens in use. The rishi chat reports them. Before the chat reports any, and after `hist` is rewritten until it reports again, this is `window_tokens`. Before the model starts, this estimates the resumed conversation."
        try:
            if self.chat:
                n = self.chat.token_count
                if self._rewrote is not None and n == self._rewrote: n = self._est
                else: self._rewrote = None
                if not n: n = self.window_tokens()   # a hosted chat counts 0 until its first step, whatever its briefing holds
                self._used = n
            elif self._resume_hist: return max(self._used,math.ceil(margin()*sum(msg_tokens(m,self.count_tokens) for m in self._resume_hist)))
        except Exception: pass
        return self._used
    
    @property
    def pct_full(self):return self.used_tokens/max(self.spec.ctx,1)
    def pending_tokens(self,msg):
        "Tokens the pending message adds. Media is charged `img_tokens()`, never its repr."
        try:
            if self.chat and hasattr(self.chat,'render'):return self.count_tokens(self.chat.render(msg))
        except Exception:pass
        text,media = _parts(msg)
        return self.count_tokens(text)+8+img_tokens()*media
    
    def projected_tokens(self,msg):return self.used_tokens+math.ceil(margin()*self.pending_tokens(msg))
    def fits(self,msg,reserve=None):
        if not self.spec.ctx:return True
        reserve=min(1024,max(128,self.spec.ctx//4)) if reserve is None else max(0,reserve)
        return self.projected_tokens(msg)<=max(1,self.spec.ctx-reserve)
    
    def _start(self):raise NotImplementedError
    def _send(self,msg,**kw):raise NotImplementedError
    def _stream(self,msg,**kw):raise NotImplementedError
    def _oneshot(self,prompt,sp,max_tokens):raise NotImplementedError
    def _replace_hist(self,summary,keep):raise NotImplementedError
    def _usage(self):return self.use
    def _refresh(self):raise NotImplementedError

