_MK_CHAT = None
@contextmanager
def use_chat(f):
    "Build model conversations with `f` for the duration, instead of rishi's `Chat`."
    global _MK_CHAT
    old, _MK_CHAT = _MK_CHAT, f
    try: yield f
    finally: _MK_CHAT = old

QUIET_RUNTIMES = frozenset({'litert'})   #: they run the tool loop inside the engine; the text before a call never reaches us

CLAUDE_EFFORT = 'high'   #: what a Claude turn asks for; Claude Code otherwise runs the model's default, medium on Opus 5.5

ROUTINE_CBS = frozenset({'ToolReminderCallback','_ToolReminderCallback','SlidingWindowCallback'})   #: rishi's defaults (litert has its own reminder): a nag on every message, and a window that forgets with no summary

class RishiBackend(Backend):
    "The `Backend` that runs every model, local or hosted, through rishi's `Chat`."
    kind='rishi'
    effort,_no_effort,_sent='',False,''   # the level the chat was built with; set once a refusal took it away; the level this call sent
    def __init__(self,*a,max_steps=MAX_STEPS,**kw):
        self.max_steps,self._prefill,self._seen_use=max_steps,None,None; super().__init__(*a,**kw)
    @property
    def prefilled_think(self):
        "Whether this model's template opens a thinking block the model has to close."
        if self._prefill is None:self._prefill=prefills_think(self.chat)
        return self._prefill
    @property
    def narrates(self): return self.spec.runtime not in QUIET_RUNTIMES
    @property
    def tool_channel(self):
        "The channel this backend's tool schemas travel on: `tool_mode` given to it is the session's choice."
        return tool_channel(self.spec,session=self.kw.get('tool_mode',''))
    def _runtime_kw(self):
        "The chat's options. `tool_mode` and `effort` go only where they differ from the runtime's default. This keeps the key of a recorded answer unchanged."
        kw={**getattr(self.spec, 'config', {}), **self.kw}
        if key_env := kw.pop('api_key_env', None): kw['api_key'] = os.environ.get(key_env)
        rt,ch,eff=self.spec.runtime,self.tool_channel,kw.pop('effort',None)
        kw.pop('tool_mode',None)
        if (rt in ('remote','copilot') and ch=='tags') or (rt=='claude' and ch=='native'): kw['tool_mode']=ch
        if rt in ('llama','ollama'): kw.setdefault('n_ctx',self.spec.ctx)
        own=model_setting(self.spec.name,self.spec.model_id).get('effort')
        if rt=='claude': eff=eff or env('EFFORT') or own or setting('runtime.effort') or CLAUDE_EFFORT
        if rt in EFFORT_RUNTIMES and (eff:=eff or own) and not self._no_effort: kw['effort']=eff
        if rt=='claude':
            kw.setdefault('on_stall',self.notice)
            kw.setdefault('timeout_hint',f'timeout under [model."{self._cfg_name()}"] in {config_path()}')
        if self.spec.runtime=='litert':
            eng=dict(kw.pop('eng_kw',{}) or {})
            if 'backend' not in eng and 'backend' not in kw and (backend := env('LITERT_BACKEND') or setting('runtime.litert_backend')):
                from litert_lm import Backend as LB
                backends = {'cpu': LB.CPU, 'gpu': LB.GPU}
                if backend.lower() not in backends: raise ValueError(f'unknown LiteRT backend {backend!r}; use cpu or gpu')
                kw['backend'] = backends[backend.lower()]()
            eng.setdefault('max_num_tokens',self.spec.ctx)
            kw['eng_kw']=eng
            if conv := dict(kw.pop('conv_kw',{}) or {}): kw['conv_kw']=conv
        return kw
    def _cfg_name(self):
        "The `[model.\"NAME\"]` table config.toml holds for this model, else the name to give a new one."
        return first(n for n in (self.spec.name,self.spec.model_id) if n in (setting('model') or {})) or self.spec.name
    def _measure(self):
        "Narrow the window to what the model was trained for, capped by what is worth filling."
        if not self.spec.local: return
        if real := local_window(self.spec.runtime,self.spec.model_id):
            from dataclasses import replace
            self.spec=replace(self.spec,ctx=min(real,local_ctx(self.spec.name)))
    def _start(self):
        from rishi import Chat
        self._measure()
        mid=claude_wire(self.spec.model_id) if self.spec.runtime=='claude' else self.spec.model_id
        kw=self._runtime_kw(); self.effort=kw.get('effort') or ''
        return self._lean(self._fitted((_MK_CHAT or Chat)(mid,runtime=self.spec.runtime,sp=self.sp,
                    tools=self.tools,approve=self.approve,tool_max_len=self.tool_max_len,
                    max_steps=self.max_steps,ctx_limit=self.spec.ctx,**kw)))
    def _lean(self,chat):
        "Leave compaction to `Compactor`: drop rishi's per-message reminder and its summary-less window, keep usage."
        if (drop:=getattr(chat,'remove_cb',None)) is None: return chat
        for c in [c for c in getattr(chat,'cbs',()) if type(c).__name__ in ROUTINE_CBS]: drop(c)
        return chat
    def _fitted(self,chat):
        "Take the window from the engine."
        try: real=int(chat.engine.n_ctx())
        except Exception: return chat
        if real and real<self.spec.ctx:
            from dataclasses import replace
            self.spec=replace(self.spec,ctx=real); chat.ctx_limit=real
        return chat
    def spawn(self,sp='',tools=(),**kw):
        if self.start() is None:raise RuntimeError(self.note)
        shared={'engine':self.chat.engine} if self.spec.local and hasattr(self.chat,'engine') else {}
        return type(self)(self.spec,sp=sp,tools=tools,tool_max_len=self.tool_max_len,
                          max_steps=self.max_steps,shared=True,**shared,**kw)
    def _turn_kw(self, kw):
        "This turn's generation controls: its `reasoning_effort` becomes the chat's `effort` for this call only, on a runtime that takes one."
        kw = dict(kw or {})
        e = str(kw.pop('reasoning_effort', None) or kw.pop('effort', None) or '').strip().lower()
        self._sent = ''
        if e in ('', 'auto', 'default') or e in self._refused or self.spec.runtime not in EFFORT_RUNTIMES: return kw
        if self.spec.runtime != 'claude' or e in EFFORTS: kw['effort'] = self._sent = e
        return kw
    def _send(self,msg,**kw):
        try: return answer_only(resp_text(self.chat(msg,**self._turn_kw(kw))))
        finally: self._dropped()
    def _dropped(self):
        "Tell the caller, once, that the provider refused the effort; a refused per-turn level is not sent again, and the chat goes back to its own."
        if not getattr(self.chat,'dropped_effort',None): return
        if self._sent: self._refuse(self._sent); self.chat.dropped_effort=None
        elif not self._no_effort: self._no_effort=True; self.fell_back.append(self.problem(f'{self.spec.name} refused effort {self.effort or "its level"}; it ran at its default'))
    def _refuse(self,level):
        "Stop sending the per-turn `level`, and say what ran instead."
        self._refused.add(level)
        self.fell_back.append(self.problem(f'{self.spec.name} refused effort {level}; it ran at {self.effort or "its default"}'))
    MCP_REFUSED=('mcp','strict_mcp_config','allowed_tools','disallowed','not permitted','policy')
    EFFORT_REFUSED=('invalid','unsupported','not supported','not allowed','refus')
    def _effort_refused(self,e):
        "The level `e` refused, the one this call sent or the chat's own, else ''."
        if not (lvl:=self._sent or ('' if self._no_effort else self.effort)): return ''
        try:
            from rishi.remote import effort_refused
            if effort_refused(e): return lvl
        except ImportError: pass
        s=f'{e}'.lower()
        return lvl if 'effort' in s and any(w in s for w in self.EFFORT_REFUSED) else ''
    def _recover(self,e):
        "Learn that this model's wire tool channel is closed, and retry on tags; or that it refused the effort, and retry without one. Returns the cause."
        if self.tools and self.tool_channel!='tags' and any(s in f'{e}'.lower() for s in self.MCP_REFUSED):
            force_tags(self.spec.model_id,agent_err(e)); why='mcp'
            self.fell_back.append(self.problem(f'{self.spec.name}: the wire refused the tool schemas, so they now travel in '
                         f'the system prompt instead ({agent_err(e)})'))
        elif (lvl:=self._effort_refused(e)) and lvl==self._sent: self._refuse(lvl); why='turn effort'
        elif lvl:
            self._no_effort,why=True,'effort'
            self.fell_back.append(self.problem(f'{self.spec.name} refused effort {lvl}; it ran at its default'))
        else: return False
        hist=self.hist
        self.close(); self.retry()
        if self.chat is None:return False
        if hist:self.restore_hist(hist)
        return why
    def _check_reply(self,text):
        "Report a tag call that came back as prose."
        if self._needs_tag_retry(text):
            how=('a <tool_call> block came back as prose' if '<tool_call' in (text or '')
                 else 'a tool call came back as bare JSON, with no <tool_call> tags around it')
            self.problem(f'{self.spec.name}: {how} rather than as a call, so this model is not '
                         'punctuating the tags channel reliably')
        return text
    def _needs_tag_retry(self,text):
        "A reply on the tags channel that shows a call it never made."
        from urai import tag_call_shape
        if self.tool_channel!='tags': return False
        return tag_call_shape(text,[getattr(t,'__name__','') for t in self.tools])
    def _stream(self,msg,**kw):
        try: yield from self._streamed(msg,**self._turn_kw(kw))
        finally: self._dropped()
    def _streamed(self,msg,**kw):
        if not self.prefilled_think:yield from self.chat(msg,stream=True,**kw); return
        from urai import StreamFormatter
        f=ThinkFilter()
        yield from StreamFormatter().format_stream(f(self.chat(msg,stream='raw',**kw)))
        if f.thought and not f.answer:
            self.problem(f'{self.spec.name} spent the whole turn thinking ({f.thought} characters) '
                         'and never answered; route `turn` to a larger model, or raise its output cap')
    def _oneshot(self,prompt,sp,max_tokens):
        if max_tokens is None: max_tokens=oneshot_tokens(self.spec.ctx)
        if self.spec.runtime!='mlx':
            return self.chat.oneshot(prompt,sp,think=False,max_tokens=max_tokens)
        if getattr(self,'_oneshot_chat',None) is None:
            if not hasattr(self.chat,'engine'):   # a replayed chat has no engine
                return self.chat.oneshot(prompt,sp,think=False,max_tokens=max_tokens)
            from rishi import Chat
            self._oneshot_chat=Chat(self.spec.model_id,runtime='mlx',engine=self.chat.engine,think=False,
                                    sp=sp,ctx_limit=self.spec.ctx,max_output_tokens=oneshot_tokens(self.spec.ctx))
        c=self._oneshot_chat
        c.sp=sp
        c.hist[:]=[c.mk_msg(prompt)]
        return resp_text(c._model_step(max_output_tokens=max_tokens))
    def _replace_hist(self,summary,keep):
        if not hasattr(self.chat,'_recreate_conv'):
            raise RuntimeError(f'{type(self.chat).__name__} cannot have its history replaced')
        self.chat.hist[:]=self.chat.mk_msgs([summary,*keep]); self.chat._recreate_conv()
    def _usage(self):
        "Cumulative, as `Backend.send` expects, though rishi's `Chat` starts a fresh `use` on every call."
        if (u:=getattr(self.chat,'use',None)) is None: return Usage(model=self.spec.model_id)
        if u is not self._seen_use: self._seen_use,self._use_base=u,self.use
        return self._use_base+Usage(model=u.model or self.spec.model_id,input=u.prompt_tokens,output=u.completion_tokens,
                     total=u.total_tokens,cached=u.cached_tokens,cache_write=u.cache_creation_tokens,
                     reasoning=u.reasoning_tokens,cost=u.cost,turns=u.n)
    def _refresh(self): self.chat.reconfigure(sp=self.sp,tools=self.tools)

def __getattr__(name):
    if name in ('LlamaBackend','FastllmBackend'):
        import warnings
        warnings.warn(f'{name} is a deprecated alias for RishiBackend; model execution goes '
                      'through Rishi for every runtime. Use RishiBackend.',
                      DeprecationWarning, stacklevel=2)
        return RishiBackend
    raise AttributeError(f'module {__name__!r} has no attribute {name!r}')

def make_backend(spec,**kw):return RishiBackend(spec,**kw)

