STATUS_CHARS = 80   #: longest status line kept

_NOT_SAID = re.compile(r'^\s*(>|```|~~~|$)')   # thinking quotes, code fences, blank lines
_BULLET = re.compile(r'^\s*(?:[-*+]|\d+[.)])\s+')

def status_line(text, n=STATUS_CHARS):
    "The last line of `text` worth showing as a status, without bullet or bold, clipped to `n` chars."
    line = next((l for l in reversed(str(text or '').splitlines()) if not _NOT_SAID.match(l)), '')
    return ' '.join(_BULLET.sub('', line).replace('**', '').split())[:n].rstrip()

def said_before_call(hist):
    "The text of the message that made the latest tool call in `hist`, or ''."
    m = next((m for m in reversed(hist or ()) if isinstance(m, dict) and m.get('role') == 'assistant'), None)
    return resp_text(m) if m and m.get('tool_calls') else ''

def _note(text):
    "What `text` said, for the pane's notes: no thinking quotes, fences or blank lines."
    return '\n'.join(l.rstrip() for l in str(text or '').splitlines() if not _NOT_SAID.match(l)).strip()

CHILD_KEEP = 50   #: finished children a run keeps; live ones are never dropped
NOTE_KEEP = 100   #: narration notes a run keeps for the pane
AIR_CALLS = 8     #: calls in a row with nothing said before the model is reminded to tell the user where it is
AIR_CHARS = 100   #: what a model must say before a call for the call to count as telling the user
REPEAT_CALLS = 3  #: identical calls in a row with an identical result before the model is told it is looping

@dataclass
class Run:
    "A foreground or delegated model call with bounded cancellation."
    id: str
    kind: str = 'root'
    question: str = ''
    model: str = ''
    parent: object = None
    grace: float = 0.25
    state: str = 'pending'
    started: float = 0.
    ended: float = 0.
    backend: object = None
    log: object = None
    status: str = ''          # what its model last said it was doing
    answer: str = ''          # the reply it finished with

    def __post_init__(self):
        self.children, self._lock, self._done, self.inbox, self._heard, self.notes = [], threading.RLock(), threading.Event(), [], [], []
        self.key, self.silent, self._same = uuid.uuid4().hex[:8], 0, (None, None, 0)
        self.tree_calls = 0
        if self.parent is not None: self.parent._adopt(self)
        if self.log is None and getattr(self.parent, 'log', None) is not None: self.log = self.parent.log.parent/f'{self.id}.log'

    def _adopt(self, child):
        "Add `child`, dropping the oldest finished children beyond `CHILD_KEEP`."
        with self._lock:
            self.children.append(child)
            if (n := len(self.children) - CHILD_KEEP) <= 0: return
            old = [c for c in self.children if c.terminal][:n]
            self.children = [c for c in self.children if all(c is not o for o in old)]

    def branch(self):
        "The top-level delegation this run belongs to: the turn's child it descends from, else the parentless run that is one itself."
        r = self
        while r.parent is not None and not (r.parent.parent is None and r.parent.kind == 'root'): r = r.parent
        return r

    def draw(self, limit, per_branch=False):
        "Count one tool call against this run's whole tree, or with `per_branch` its top-level delegation's; False once `limit` calls are spent."
        owner = self.branch() if per_branch else self
        while not per_branch and owner.parent is not None: owner = owner.parent
        with owner._lock:
            owner.tree_calls += 1
            return limit is None or owner.tree_calls <= limit

    def write(self, line):
        "Append one transcript line, when this run keeps a transcript."
        if self.log is None: return
        self.log.parent.mkdir(parents=True, exist_ok=True)
        with self._lock, open(self.log, 'a') as f: f.write(f'{time.strftime("%H:%M:%S")} {line}\n')

    def tell(self, text):
        "Queue a user message for whoever is working this run; `drain_inbox` hands it over."
        with self._lock: self.inbox.append(str(text))
        self.write(f'user: {text}')

    def drain_inbox(self):
        "Every queued user message, taken once. A message handed over restarts the `air` count: the next reply answers it."
        with self._lock:
            out, self.inbox = self.inbox, []
            if out: self.silent = 0
        return out

    def set_status(self, text):
        "Make `text`'s last line the status, noting a new one in the transcript."
        if (s := status_line(text)) and s != self.status:
            self.status = s
            self.write(f'~ {s}')
        return self

    def hear(self, text):
        "Keep streamed text until the next tool call."
        with self._lock: self._heard.append(text)

    def on_call(self):
        "A call is starting: what was streamed since the last, else the message that made it, becomes the status."
        with self._lock: said, self._heard = ''.join(self._heard), []
        if not status_line(said): said = said_before_call(getattr(self.backend, 'hist', None))
        with self._lock:   # a message making several calls starts each one here, and is still one note
            if (n := _note(said)) and not (self.notes and self.notes[-1][1] == n): self.notes = [*self.notes, (time.time(), n)][-NOTE_KEEP:]
            self.silent = 0 if len(n) >= AIR_CHARS else self.silent + 1
        return self.set_status(said)

    def repeated(self, call, result):
        "How many calls in a row have been `call` returning `result`, this one included."
        with self._lock:
            last, seen, n = self._same
            n = n + 1 if (call, result) == (last, seen) else 1
            self._same = (call, result, n)
        return n

    def air(self):
        "A reminder to tell the user where the work is, once `AIR_CALLS` calls in a row went by with nothing said; else ''. A sub-agent's run is never reminded, since it reports to its caller."
        with self._lock:
            if self.kind != 'root' or self.silent < AIR_CALLS: return ''
            n, self.silent = self.silent, 0
        asked = ' '.join(str(self.question).split())[:300]
        return (f'{n} tool calls have gone by without a message to the user. Before the next call, tell them in a few '
                f'sentences what you have found and what you are doing next. Their request was: "{asked}"')

    @property
    def terminal(self): return self.state in ('completed', 'cancelled', 'detached', 'terminated', 'failed')
    @property
    def cancelled(self): return self.state in ('cancelling', 'cancelled', 'detached', 'terminated')

    def child(self, question='', model=''):
        return Run(f'run_{uuid.uuid4().hex[:12]}', 'child', question, model, self, self.grace)

    def start(self, backend=None):
        with self._lock:
            if self.state != 'pending': return False
            self.state, self.backend, self.started = 'running', backend, time.time()
            return True

    def attach(self, backend):
        with self._lock:
            self.backend = backend
            cancelled = self.cancelled
        if cancelled and backend is not None:
            threading.Thread(target=lambda: backend.cancel(), daemon=True).start()
        return not cancelled

    def finish(self, state='completed'):
        with self._lock:
            if self.terminal: return self
            self.state = 'cancelled' if self.cancelled else state
            self.ended, self._heard = time.time(), []
            self._done.set()
        return self

    def _mark_cancel(self):
        "Mark this run and every descendant cancelled, and return the backends left to stop."
        # mark all before stopping any, or a freed worker spawns a cancelled run's sibling
        with self._lock:
            if self.terminal: return []
            pending = self.state == 'pending'
            self.state = 'cancelling'
            children, backend = list(self.children), None if pending else self.backend
        if pending: self.finish('cancelled')
        out = [] if backend is None else [backend]
        for child in children: out += child._mark_cancel()
        return out

    def request_cancel(self):
        for backend in self._mark_cancel():
            threading.Thread(target=lambda b=backend: b.cancel(), daemon=True).start()
        return self

    def terminate(self):
        with self._lock:
            if self.state in ('completed', 'cancelled', 'terminated', 'failed'): return self
            children, backend = list(self.children), self.backend
        for child in children: child.terminate()
        if backend is not None:
            f = getattr(backend, 'terminate', None) or getattr(backend, 'close', None)
            if f is not None: threading.Thread(target=f, daemon=True).start()
        with self._lock:
            self.state, self.ended = 'terminated', time.time(); self._done.set()
        return self

    def wait(self, grace=None):
        end = time.monotonic() + (self.grace if grace is None else max(0, grace))
        for child in list(self.children):
            left = max(0, end - time.monotonic())
            child._done.wait(left)
            if not child.terminal: child.detach()
        left = max(0, end - time.monotonic())
        self._done.wait(left)
        if not self.terminal: self.detach()
        return self

    def detach(self):
        with self._lock:
            if self.terminal: return self
            self.state, self.ended = 'detached', time.time(); self._done.set()
        for child in list(self.children):
            if not child.terminal: child.detach()
        return self

    def cancel(self, grace=None): return self.request_cancel().wait(grace)

    def dict(self):
        return {'id': self.id, 'parent_id': getattr(self.parent, 'id', None), 'kind': self.kind,
                'question': self.question, 'model': self.model, 'state': self.state,
                'started': self.started, 'ended': self.ended, 'log': None if self.log is None else str(self.log),
                'children': [child.dict() for child in self.children]}


